        internal
    {
        // When bridging using a native token the `value` must include the `_gasLimit` and `amount` before being
        // sent to the MetaERC20HubOrSpoke smart contract. Only the amount is burned and the `gasLimit` is used to pay
        // for the
        // cross-chain message.
